const jwt = require('jsonwebtoken');
function generateToken(privateKey) {
  return jwt.sign({ iss: 'svc' }, privateKey, { algorithm: 'ES256', expiresIn: '1h' });
}
function makeAssertion(claims, pk) {
  return jwt.sign(claims, pk, { algorithm: 'RS256' });
}
async function push(creds, payload) {
  return fetch('https://push.example.invalid/notify', {
    method: 'POST',
    headers: { authorization: 'bearer ' + generateToken(creds.privateKey) },
    body: JSON.stringify({ assertion: makeAssertion(payload, creds.private_key) }),
  });
}
module.exports = { push };

